    const preset = VIEWPORTS[n];
    if (preset) return preset;
    const m = n.match(/^(\d{3,4})x(\d{3,4})$/);
    if (m) {
      const width = Number(m[1]);
      const mobile = width < 768;
      return {
        name: n,
        width,
        height: Number(m[2]),
        deviceScaleFactor: 1,
        isMobile: mobile,
        hasTouch: mobile
      };
    }
